(function(root){'use strict';
const App=root.MT_WORKSPACE_APP;
async function api(path,method='GET',data,revision){const headers={};if(data!==undefined)headers['content-type']='application/json';if(revision!==undefined)headers['if-match']=String(revision);const response=await fetch('/api/workspace'+path,{method,credentials:'same-origin',cache:'no-store',headers,body:data===undefined?undefined:JSON.stringify(data)});let result;try{result=await response.json();}catch{throw Error('Account services are unavailable here. Open the authenticated private preview to use them.');}if(!response.ok){const e=Error(result.error||'Account request failed.');e.status=response.status;throw e;}return result;}
async function account(c){let remote=null,local=null;return {html:'<h1>Account synchronization</h1><p class="next-intro">Choose what to transfer, compare both versions and decide which records to keep. Local work remains available without synchronization.</p>'+c.subnav([['account','Account sync'],['classes','Classes & assignments']])+'<section class="panel"><h2>Cross-device backup</h2><p>Account storage uses your signed-in identity on this private preview. Only the selected records are transferred. A class submission is shared separately with its class owner.</p><label class="check"><input id="sync-enable" type="checkbox">Enable account transfer for this session</label><fieldset><legend>Selected records</legend>'+Object.entries(c.W.groups).map(([key,g])=>'<label class="check"><input name="sync-group" type="checkbox" value="'+key+'"'+(['workspace','learning'].includes(key)?' checked':'')+'>'+c.esc(g.title)+'</label>').join('')+'</fieldset><div class="next-actions"><button id="sync-compare" disabled>Read account snapshot and compare</button><button id="sync-delete" disabled>Delete account snapshot</button></div><div id="sync-comparison"></div><p id="sync-result" role="status"></p></section>',bind(){const groups=()=>[...document.querySelectorAll('[name=sync-group]:checked')].map(n=>n.value),invalidate=()=>{remote=null;local=null;c.$('sync-comparison').textContent='';c.$('sync-delete').disabled=true;};c.on('sync-enable','change',()=>{invalidate();c.$('sync-compare').disabled=!c.$('sync-enable').checked;});document.querySelectorAll('[name=sync-group]').forEach(n=>n.addEventListener('change',invalidate));c.button('sync-compare',async()=>{invalidate();if(!c.$('sync-enable').checked||!groups().length)throw Error('Enable account transfer and select at least one group.');await api('/session');remote=await api('/sync');local=c.W.backup(c.storage,groups());const entries=remote.backup?c.W.validateBackup(remote.backup).entries:{},keys=[...new Set([...Object.keys(local.entries),...Object.keys(entries).filter(k=>groups().some(g=>c.W.groups[g].test(k)))])].sort();c.$('sync-comparison').innerHTML='<h3>Compare records · account revision '+remote.revision+'</h3><p>Choosing Local or Account selects the complete record, including its history. Separate records can be combined; individual attempts inside a record are not automatically merged.</p>'+keys.map((key,i)=>'<fieldset><legend>'+c.esc(key)+'</legend><p>'+((local.entries[key]===entries[key])?'Same value':!local.entries[key]?'Account only':!entries[key]?'Local only':'Different versions')+' · Local '+(local.entries[key]?.length||0)+' characters · Account '+(entries[key]?.length||0)+' characters</p><label>Keep<select data-sync-key="'+i+'">'+c.options([['local','Local version'],['remote','Account version']],local.entries[key]===undefined?'remote':'local')+'</select></label></fieldset>').join('')+'<div class="next-actions"><button id="sync-push">Upload selected versions</button><button id="sync-pull">Apply selected versions locally</button></div>';c.$('sync-delete').disabled=!remote.backup;function chosen(){if(!remote||!local||!c.$('sync-enable').checked)throw Error('Compare the current snapshot first.');const merged={...local,entries:{}};keys.forEach((key,i)=>{const from=document.querySelector('[data-sync-key="'+i+'"]').value==='remote'?entries:local.entries;if(from[key]!==undefined)merged.entries[key]=from[key];});return c.W.validateBackup(merged);}c.button('sync-push',async()=>{const selected=chosen();const complete={...(remote.backup||selected),entries:{...(remote.backup?.entries||{})}};for(const key of keys)delete complete.entries[key];Object.assign(complete.entries,selected.entries);try{const out=await api('/sync','PUT',{backup:complete},remote.revision);invalidate();c.$('sync-result').textContent='Account snapshot saved at revision '+out.revision+'.';}catch(e){if(e.status===409)invalidate();throw e;}});c.button('sync-pull',()=>{const selected=chosen();if(!confirm('Replace these selected local records with the versions shown?'))return;c.download('MarineTools-before-account-restore.json',JSON.stringify(c.W.backup(c.storage,groups()),null,2));c.W.restore(c.storage,selected,groups());invalidate();c.$('sync-result').textContent='Selected records restored. Reload the workspace before continuing.';});});c.button('sync-delete',async()=>{if(!remote||!confirm('Delete the account snapshot? This leaves local records and classes in place.'))return;await api('/sync','DELETE',undefined,remote.revision);invalidate();c.$('sync-result').textContent='Account snapshot deleted.';});}};}
async function classes(c){await api('/session');const selected=c.params.get('class'),assignmentId=c.params.get('assignment');if(assignmentId)return assignmentView(c,assignmentId);if(selected)return classView(c,selected);const data=await api('/classes');return {html:'<h1>Classes & assignments</h1><p class="next-intro">Create a class for teaching or join with a code from your teacher. Your chosen display name and submitted answers are visible to the class owner.</p>'+c.subnav([['account','Account sync'],['classes','Classes & assignments']])+'<div class="next-grid"><section class="panel"><h2>Create a class</h2><form id="class-create"><label>Class name<input id="class-name" maxlength="120" required></label><button>Create class</button></form></section><section class="panel"><h2>Join a class</h2><form id="class-join"><label>Join code<input id="class-code" maxlength="100" required autocomplete="off"></label><label>Your display name<input id="class-display-name" maxlength="80" required autocomplete="off"></label><button>Join class</button></form></section></div><section class="panel"><h2>Your classes</h2>'+(data.classes.length?data.classes.map(v=>'<p><a href="#classes?class='+encodeURIComponent(v.id)+'">'+c.esc(v.name)+' · '+(v.owner?'Teacher':'Learner')+' →</a></p>').join(''):c.empty('You have not created or joined a class.'))+'</section>',bind(){c.on('class-create','submit',async e=>{e.preventDefault();const out=await api('/classes','POST',{name:c.$('class-name').value});location.hash='classes?class='+out.id;});c.on('class-join','submit',async e=>{e.preventDefault();const out=await api('/classes/join','POST',{code:c.$('class-code').value,displayName:c.$('class-display-name').value});location.hash='classes?class='+out.id;});}};}
async function classView(c,id){const cls=await api('/classes/'+encodeURIComponent(id));return {html:'<h1>'+c.esc(cls.name)+'</h1><p><a href="#classes">← All classes</a></p><section class="panel"><h2>Assignments</h2>'+cls.assignments.map(a=>'<article class="next-step"><a href="#classes?assignment='+a.id+'">'+c.esc(a.title)+' →</a><p>'+(a.due_at?'Due '+c.esc(new Date(a.due_at).toLocaleString()):'No deadline')+'</p></article>').join('')+(cls.assignments.length?'':c.empty('No assignments yet.'))+'</section>'+(cls.owner?'<section class="panel"><h2>Class access</h2><p>Share this code only with intended learners: <strong>'+c.esc(cls.joinCode)+'</strong></p><p>This preview currently requires access to the private site as well as a class code.</p>'+c.table(['Learner','Joined'],cls.members.map(m=>[m.display_name,new Date(m.joined_at).toLocaleString()]))+'</section><section class="panel"><h2>Create an assignment</h2><form id="assignment-create"><label>Title<input id="assignment-title" required maxlength="200"></label><div class="fields"><label>Chapter<select id="assignment-chapter">'+c.chapterOptions(1)+'</select></label><label>Questions<input id="assignment-count" type="number" min="1" max="50" step="1" value="5" required></label><label>Optional due date<input id="assignment-due" type="datetime-local"></label></div><button type="button" id="assignment-preview">Preview questions</button><div id="assignment-questions"></div><button id="assignment-save" disabled>Create reviewed assignment</button></form></section><section class="panel"><h2>Delete class</h2><p>This removes the class, memberships, assignments and submissions from account storage.</p><button id="class-delete">Delete this class</button></section>':'<section class="panel"><button id="class-leave">Leave this class and remove my submissions</button></section>'),bind(){let chosen=null;c.button('assignment-preview',async()=>{chosen=null;c.$('assignment-save').disabled=true;const [chapter]=await c.chapters([Number(c.$('assignment-chapter').value)]),count=Number(c.$('assignment-count').value);if(!Number.isInteger(count)||count<1||count>chapter.questions.length)throw Error('Choose a whole question count within this chapter.');chosen=chapter.questions.slice(0,count);c.$('assignment-questions').innerHTML='<ol>'+chosen.map(q=>'<li>'+c.esc(q.prompt)+' · '+c.esc(q.unit)+'</li>').join('')+'</ol>';c.$('assignment-save').disabled=false;});for(const name of ['assignment-chapter','assignment-count'])c.on(name,'input',()=>{chosen=null;c.$('assignment-save').disabled=true;});c.on('assignment-create','submit',async e=>{e.preventDefault();if(!chosen)throw Error('Review the questions first.');const due=c.$('assignment-due').value,result=await api('/classes/'+id+'/assignments','POST',{title:c.$('assignment-title').value,items:chosen,dueAt:due?new Date(due).getTime():null});location.hash='classes?assignment='+result.id;});c.button('class-delete',async()=>{if(confirm('Permanently delete this class and all of its assignments and submissions?')){await api('/classes/'+id,'DELETE');location.hash='classes';}});c.button('class-leave',async()=>{if(confirm('Leave this class and remove your submitted answers?')){await api('/classes/'+id+'/membership','DELETE');location.hash='classes';}});}};}
async function assignmentView(c,id){const a=await api('/assignments/'+encodeURIComponent(id)),roster=a.owner?await api('/assignments/'+id+'/submissions'):null;return {html:'<h1>'+c.esc(a.title)+'</h1><p><a href="#classes?class='+a.classId+'">← Class</a></p><section class="panel"><p>'+(a.dueAt?'Due '+c.esc(new Date(a.dueAt).toLocaleString()):'No deadline')+'</p>'+(a.submission?'<p>Latest submission: '+a.submission.score+' / '+a.submission.total+' · attempt '+a.submission.attempts+'</p>':'')+'<form id="assignment-submit">'+a.items.map((q,i)=>'<article class="next-step"><h2>'+(i+1)+'. '+c.esc(q.prompt)+'</h2>'+(!a.owner?'<label>Your answer · '+c.esc(q.unit)+'<input type="text" inputmode="decimal" maxlength="100" data-assignment-answer="'+c.esc(q.id)+'" value="'+c.esc(a.submission?.answers[q.id]||'')+'"></label>':'')+(q.steps?'<details><summary>Worked solution</summary><ol>'+q.steps.map(s=>'<li>'+c.esc(s)+'</li>').join('')+'</ol></details>':'')+'</article>').join('')+(!a.owner?'<button>Submit answers to your teacher</button>':'')+'</form><div id="assignment-result" role="status"></div></section>'+(a.owner?'<section class="panel"><h2>Submissions</h2><button id="assignment-refresh">Refresh submissions</button>'+c.table(['Learner','Score','Attempts','Submitted'],roster.submissions.map(r=>[r.display_name,r.score+' / '+r.total,r.attempts,new Date(r.submitted_at).toLocaleString()]))+'<div class="next-actions"><button id="assignment-xml">Export Moodle questions</button><button id="assignment-csv">Export grade table</button><button id="assignment-delete">Delete assignment</button></div></section>':''),bind(){c.on('assignment-submit','submit',async e=>{e.preventDefault();const answers=Object.fromEntries([...document.querySelectorAll('[data-assignment-answer]')].map(v=>[v.dataset.assignmentAnswer,v.value]));if(!confirm('Submit these answers to the class owner?'))return;const result=await api('/assignments/'+id+'/submissions','POST',{answers});c.$('assignment-result').innerHTML='<h2>'+result.score+' / '+result.total+(result.late?' · submitted after deadline':'')+'</h2>'+result.grades.map((g,i)=>'<article><h3>Question '+(i+1)+' · '+(g.correct?'Correct':'Review')+'</h3><ol>'+g.steps.map(s=>'<li>'+c.esc(s)+'</li>').join('')+'</ol></article>').join('');});c.button('assignment-refresh',()=>c.refresh());c.button('assignment-xml',async()=>{await c.load('workspace-lms-20261030.js');c.download('MarineTools-assignment.xml',root.MT_LMS.moodle(a.items),'application/xml');});c.button('assignment-csv',()=>c.download('MarineTools-grades.csv',c.E.csv([['Learner','Score','Total','Attempts','Submitted'],...roster.submissions.map(r=>[r.display_name,r.score,r.total,r.attempts,new Date(r.submitted_at).toISOString()])]),'text/csv'));c.button('assignment-delete',async()=>{if(confirm('Delete this assignment and all its submissions?')){await api('/assignments/'+id,'DELETE');location.hash='classes?class='+a.classId;}});}};}
root.MT_ACCOUNT_API=api;App.register({account,classes});
})(window);
